import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {
            Unstoppable u = new Unstoppable();
            u.solve(br, pw);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    static class Unstoppable {
        public void solve(BufferedReader in, PrintWriter out) throws IOException {
            String[] line = in.readLine().split(" ");
            int n = Integer.parseInt(line[0]);
            long b = Long.parseLong(line[1]);
            int[] a = new int[n];
            int[] c = new int[n];
            String[] nums = in.readLine().split(" ");
            for (int i = 0; i < n; i++) {
                a[i] = Integer.parseInt(nums[i]);
                c[i] = (a[i] % 2 == 0) ? 1 : -1;
            }
            long sum = 0;
            ArrayList<Integer> diffList = new ArrayList<>();
            for (int i = 0; i < n - 1; i++) {
                sum += c[i];
                if (sum == 0) {
                    diffList.add(Math.abs(a[i] - a[i + 1]));
                }
            }
            Collections.sort(diffList);
            long total = 0;
            int count = 0;
            for (int diff : diffList) {
                total += diff;
                if (total <= b) {
                    count++;
                } else {
                    break;
                }
            }
            out.println(count);
        }
    }
}
